export function normalizeRanges(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError('ranges must be an array');
  }
  const sorted = [];
  for (const member of ranges) {
    if (!Array.isArray(member) || member.length !== 2) {
      throw new TypeError('each range must be an array of exactly two finite numbers');
    }
    const start = member[0];
    const end = member[1];
    if (
      typeof start !== 'number' ||
      typeof end !== 'number' ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    ) {
      throw new TypeError('each range must be an array of exactly two finite numbers');
    }
    if (start > end) {
      throw new RangeError('range start must be less than or equal to end');
    }
    if (start === end) {
      continue;
    }
    sorted.push([start, end]);
  }
  sorted.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (const [start, end] of sorted) {
    if (merged.length === 0) {
      merged.push([start, end]);
      continue;
    }
    const last = merged[merged.length - 1];
    if (start <= last[1]) {
      if (end > last[1]) {
        last[1] = end;
      }
    } else {
      merged.push([start, end]);
    }
  }
  return merged.map(([s, e]) => [s, e]);
}

