import { normalizeRanges } from './normalize-ranges.mjs';

export function subtractRanges(base, removed) {
  let result = normalizeRanges(base).map(([start, end]) => [start, end]);
  const cuts = normalizeRanges(removed);
  for (const [cutStart, cutEnd] of cuts) {
    const next = [];
    for (const [start, end] of result) {
      if (cutEnd <= start || cutStart >= end) {
        next.push([start, end]);
        continue;
      }
      if (cutStart > start) {
        next.push([start, cutStart]);
      }
      if (cutEnd < end) {
        next.push([cutEnd, end]);
      }
    }
    result = next;
  }
  return result;
}

